import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"资料、引用与核验说明","description":"说明《人生进阶指南》怎样区分研究结论、个人经验与待检验假设，AI 资料按什么周期复核，以及怎样规范地引用本书。","frontmatter":{"title":"资料、引用与核验说明","description":"说明《人生进阶指南》怎样区分研究结论、个人经验与待检验假设，AI 资料按什么周期复核，以及怎样规范地引用本书。","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"reference/sources-and-citation.md","filePath":"reference/sources-and-citation.md","lastUpdated":1795392000000}'),s={name:"reference/sources-and-citation.md"};function o(r,e,l,p,d,c){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="资料、引用与核验说明" tabindex="-1">资料、引用与核验说明 <a class="header-anchor" href="#资料、引用与核验说明" aria-label="Permalink to &quot;资料、引用与核验说明&quot;">​</a></h1><p>这本书不希望读者把任何一句话当成不可质疑的结论。这一页说明三件事：书里的陈述分成哪几类，外部资料多久复核一次，以及怎样引用和更正。</p><h2 id="三类陈述" tabindex="-1">三类陈述 <a class="header-anchor" href="#三类陈述" aria-label="Permalink to &quot;三类陈述&quot;">​</a></h2><p><strong>研究结论</strong>来自公开发表的研究、官方指南或规范文档。它描述的是特定样本、材料、测量和条件下得到的结果，不能直接写成对某个人的保证。书中引用时会保留作者、年份、链接和适用边界；能核对的地方给出一手来源，不能用营销页面代替。</p><p><strong>个人经验</strong>只证明作者经历过什么。它可以是证据的一部分，但不是规律：一次失败不能推出所有人都该避免同一条路，一次恢复也不能推出同一种方法对每个人都有效。读个人故事时，请把它当作场景，而不是处方。</p><p><strong>待检验的假设</strong>是作者或读者对未来的推断。它可能正确，也可能被下一次实验推翻。书里会尽量标明“如果……那么……”的条件；没有标明的判断，你可以先当作假设处理。</p><p>三类陈述混在一起时，最容易产生“听起来都对、用起来无效”的段落。阅读时可以先问一句：这句话属于哪一类？</p><h2 id="ai-资料的复核规则" tabindex="-1">AI 资料的复核规则 <a class="header-anchor" href="#ai-资料的复核规则" aria-label="Permalink to &quot;AI 资料的复核规则&quot;">​</a></h2><p>AI 产品、模型能力、价格、套餐、协议和供应商政策变化很快。本书按变化速度分级复核：</p><ul><li><strong>30 天</strong>：使用政策、安全公告、产品功能、地区与套餐。页面会声明 <code>source_review_interval: 30</code>。</li><li><strong>60 天</strong>：协议规范、实现指南和变化较快的工作流。</li><li><strong>120 天</strong>：相对稳定的概念、研究背景和历史事实。</li></ul><p>规则如下：</p><ol><li>优先引用官方文档、正式规范或一手公告，不用二手博客代替；</li><li>记录核验日期（<code>sources_checked</code>），它与正文修改日期（<code>updated</code>）分开；</li><li>产品入口只是“可以重新核验的页面”，不是当前功能清单，也不是效果保证；</li><li>无法再次核验的页面标注为历史资料，不继续当作当前证据；</li><li>政策、价格和能力必须回到正式协议、官方页面与实际验收。</li></ol><p>如果你发现某条产品描述已经过时，欢迎按下一页的方式报告。</p><h2 id="如何引用本书" tabindex="-1">如何引用本书 <a class="header-anchor" href="#如何引用本书" aria-label="Permalink to &quot;如何引用本书&quot;">​</a></h2><p>引用时请写明书名、作者、版本、日期和网址，并注明正文采用 CC BY-NC 4.0：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>韩先凯. 人生进阶指南：一个普通人的失败、恢复与重新学习. 1.1.0 版. 2026-11-23.</span></span>
<span class="line"><span>https://byoungd.github.io/up/</span></span></code></pre></div><p>英文版：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Han Xiankai. Still Here: A Field Guide to Beginning Again. Edition 1.1.0. 23 November 2026.</span></span>
<span class="line"><span>https://byoungd.github.io/up/en/</span></span></code></pre></div><p>仓库根目录的 <a href="https://github.com/byoungd/up/blob/main/CITATION.cff" target="_blank" rel="noreferrer"><code>CITATION.cff</code></a> 提供了机器可读的引用信息。本书没有 DOI，也没有分配 ISBN；请不要自行补上一个。引用具体章节时，可以加上章节标题和页面地址，方便读者回到原文。</p><h2 id="报告来源错误" tabindex="-1">报告来源错误 <a class="header-anchor" href="#报告来源错误" aria-label="Permalink to &quot;报告来源错误&quot;">​</a></h2><p>如果你发现：</p><ul><li>引用的研究结论与原文不符；</li><li>链接失效或指向了另一个页面；</li><li>产品描述已经过时；</li><li>中文版与英文版对同一事实的表述不一致；</li></ul><p>请通过<a href="https://github.com/byoungd/up/issues/new/choose" target="_blank" rel="noreferrer">问题模板</a>提交，并写清页面、原句、你认为正确的来源和核验日期。涉及个人信息、未授权图片或安全问题的，不要公开发布，按 <code>SECURITY.md</code> 的私有渠道报告。</p><p>维护者会先核对来源，再修改正文；只改日期、不核对内容不算完成复核。</p><h2 id="参考书目" tabindex="-1">参考书目 <a class="header-anchor" href="#参考书目" aria-label="Permalink to &quot;参考书目&quot;">​</a></h2><p>按主题整理的来源清单见<a href="./bibliography">参考文献</a>。它只收录书中实际引用过的资料，不做穷举；论文与书籍不随仓库分发，读者需要自行通过 DOI 或官方链接访问。</p>`,26)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
